import{_ as a,o as i,c as e,a2 as s}from"./chunks/framework.Drubq5y2.js";const k=JSON.parse('{"title":"模块 1 — 扫描（scan_board.py）需求文档","description":"","frontmatter":{},"headers":[],"relativePath":"requirements/module-1-scan.md","filePath":"requirements/module-1-scan.md"}'),d={name:"requirements/module-1-scan.md"};function n(l,t,o,r,h,c){return i(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="模块-1-—-扫描-scan-board-py-需求文档" tabindex="-1">模块 1 — 扫描（scan_board.py）需求文档 <a class="header-anchor" href="#模块-1-—-扫描-scan-board-py-需求文档" aria-label="Permalink to &quot;模块 1 — 扫描（scan_board.py）需求文档&quot;">​</a></h1><h2 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h2><ul><li><code>--board 159/240/160</code>，默认 1 页</li></ul><h2 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h2><ul><li><code>data/new_candidates_{board}.json</code> — 过滤后通过的候选列表</li><li><code>data/candidates/scan_state.json</code> — 增量扫描状态</li><li><code>data/candidates/queue.json</code> — 入队记录</li><li><code>docs/projects/_{TID}.md</code> — 项目文件（极简版）</li></ul><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扫描板块列表页 → 提取 {TID: 标题} → is_ann_candidate 过滤</span></span>
<span class="line"><span>  → 通过的写入 new_candidates_X.json</span></span>
<span class="line"><span>  → 最新的 1 个入队 → 创建 _{TID}.md</span></span></code></pre></div><h2 id="过滤规则-is-ann-candidate" tabindex="-1">过滤规则（is_ann_candidate） <a class="header-anchor" href="#过滤规则-is-ann-candidate" aria-label="Permalink to &quot;过滤规则（is_ann_candidate）&quot;">​</a></h2><p>按顺序检查，任一条件不通过则拒绝：</p><ol><li><strong>固定帖 ID</strong> — 在 STICKY_IDS 中的跳过</li><li><strong>最小标题长度</strong> — &lt;12 字符跳过</li><li><strong>Skip 关键词</strong> — bounty/giveaway/claim/sell/bounty/spam 等 24 个关键词，子串匹配</li><li><strong>非项目正则</strong> — &quot;not allowed&quot; / &quot;will be BANNED&quot; / &quot;rules, guidelines&quot; 等 10 个正则</li><li><strong>ANN 特征匹配</strong>（以下 5 种，满足任一即通过）： <ul><li><code>[ANN]</code> 标记</li><li><code>[PRE-ANN]</code> / <code>[PREANN]</code> 标记</li><li>标题含 &quot;Announcement&quot; 单词</li><li><code>(TICKER)</code> — 括号内 2-8 位大写字母数字</li><li><code>[TICKER]</code> — 方括号内 2-6 位大写字母数字</li></ul></li><li><strong>以上都不匹配</strong> → 拒绝</li></ol><h2 id="生成的文件-tid-md" tabindex="-1">生成的文件 <code>_{TID}.md</code> <a class="header-anchor" href="#生成的文件-tid-md" aria-label="Permalink to &quot;生成的文件 \`_{TID}.md\`&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">ANN</span><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">] 标题原文</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*中文副标题*</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">（仅当翻译表中查到中文名时）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **详情页:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://bitcointalk.org/index.php?topic={TID}.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **流水线:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 模块1/10 · 已抓取</span></span></code></pre></div><ul><li>文件名：<code>_{TID}.md</code>，TID 纯数字</li><li>内容仅包含：标题、中文副标题（可选）、Bitcointalk 详情页链接、流水线阶段</li><li>不含：发布者、日期、外部链接、分析（由后续模块追加）</li></ul><h2 id="边界情况" tabindex="-1">边界情况 <a class="header-anchor" href="#边界情况" aria-label="Permalink to &quot;边界情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>某页全部已入库</td><td>gap detection 触发，停止翻页</td></tr><tr><td>网络超时</td><td>等待 5s 后重试，最多 1 次</td></tr><tr><td>请求异常</td><td>跳过当前页，继续下一页</td></tr><tr><td><code>--no-filter</code> 调试模式</td><td>关闭过滤，所有帖子写入 new_candidates_X.json</td></tr></tbody></table><h2 id="后续模块依赖" tabindex="-1">后续模块依赖 <a class="header-anchor" href="#后续模块依赖" aria-label="Permalink to &quot;后续模块依赖&quot;">​</a></h2><p>模块 2（fetch_candidates.py）通过 <code>topic={TID}</code> 字符串从 <code>_{TID}.md</code> 文件中找到对应文件，追加字段。</p><h2 id="与旧版本的差异" tabindex="-1">与旧版本的差异 <a class="header-anchor" href="#与旧版本的差异" aria-label="Permalink to &quot;与旧版本的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>旧版</th><th>新版</th></tr></thead><tbody><tr><td>文件名</td><td><code>中文名_TICKER_英文名.md</code>（基于 core_name）</td><td><code>_{TID}.md</code>（纯数字）</td></tr><tr><td>过滤</td><td>宽松（coin/token/blockchain 等放行）</td><td>收紧（只认 [ANN]/(TICKER)/[TICKER]/Announcement）</td></tr><tr><td>输出文件</td><td>写入全部扫描结果（含未过滤）</td><td>只写过滤通过的项目</td></tr><tr><td>文件名依赖</td><td>下游依赖文件名解析 ticker/中文名</td><td>下游改为从文件内容解析</td></tr></tbody></table>`,19)])])}const u=a(d,[["render",n]]);export{k as __pageData,u as default};
